Mesh<Point, double> result;
for (RT::All_edges_iterator it = rt.finite_edges_begin(); it != rt.finite_edges_end(); ++it) {
    RT::Edge edge = *it;
    RT::Cell_handle c1 = edge.first;
    RT::Cell_handle c2 = c1->neighbor(edge.second);

    // Check if edge is above threshold (using squared length)
    double squared_length = rt.segment(edge).squared_length();
    if (squared_length < threshold * threshold) {
        continue;
    }

    // Get the two vertices of the edge
    int i1 = edge.third;
    int i2 = (edge.second + 1 + i1) % 4;
    if (i2 == edge.second) i2 = (edge.second + 2) % 4;

    // Find the opposite vertices in each cell (not part of the edge)
    int opp1 = -1, opp2 = -1;
    for (int i = 0; i < 4; ++i) {
        if (i != edge.second && i != i1 && i != i2) {
            opp1 = i;
            break;
        }
    }
    for (int i = 0; i < 4; ++i) {
        if (i != edge.second && i != i1 && i != i2) {
            opp2 = i;
            break;
        }
    }

    // Get the circumcenters of the two incident cells
    // In a regular triangulation, the circumcenter of a cell is the center of the power sphere
    Point p1 = c1->circumcenter();
    Point p2 = c2->circumcenter();

    // For power diagram face, we need to collect all circumcenters around the edge
    // The face is a polygon with vertices being the circumcenters of incident cells
    // For a 3D regular triangulation, each edge has exactly two incident cells
    // So the face is just a line segment between the two circumcenters

    // Add the two vertices to the mesh
    result.vertices.push_back(p1);
    result.vertices.push_back(p2);

    // Add the face (edge) with 2 vertices
    std::vector<unsigned> face_vertices = {result.vertices.size() - 2, result.vertices.size() - 1};
    result.push_back(face_vertices, std::sqrt(squared_length));
}
return result;

