            opp_vertices.push_back(i);
        }
    }

    // Get the circumcenters of the two incident cells
    Point p1 = c1->circumcenter();
    Point p2 = c2->circumcenter();

    // Add the two vertices to the mesh
    result.vertices.push_back(p1);
    result.vertices.push_back(p2);

    // Create a face with two vertices (an edge in the power diagram)
    std::vector<unsigned> face_vertices = {result.vertices.size() - 2, result.vertices.size() - 1};
    result.push_back(face_vertices, std::sqrt(squared_length));
}
return result;

